def weighted_distance_sums(n: int, edges: list[list[int]], w: list[int]) -> list[int]:
    if n == 1:
        return [0]

    adj = [[] for _ in range(n)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    parent = [-1] * n
    order = []
    stack = [0]
    parent[0] = -2
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if parent[v] == -1:
                parent[v] = u
                stack.append(v)
    parent[0] = -1

    sub_w = w[:]
    for u in reversed(order):
        p = parent[u]
        if p != -1:
            sub_w[p] += sub_w[u]

    depth = [0] * n
    s0 = 0
    for u in order:
        if u != 0:
            depth[u] = depth[parent[u]] + 1
        s0 += w[u] * depth[u]

    total = sub_w[0]
    ans = [0] * n
    ans[0] = s0
    for u in order:
        if u == 0:
            continue
        ans[u] = ans[parent[u]] + total - 2 * sub_w[u]
    return ans
